style.css:
@-moz-document domain("google.com") {
body, html {
    background-color: #1a0d0d !important; /* dark maroon */
    color: #f8f8f8 !important;
    font-family: 'Segoe UI', sans-serif !important;
  }

  input, textarea, select, button {
    background-color: #2a0f0f !important; /* wine red */
    color: #ffdddd !important;
    border: 1px solid #5c1a1a !important;
  }

  a {
    color: #e06666 !important;
  }

  a:visited {
    color: #b34747 !important;
  }

  .RNNXgb {
    background: #330d0d !important;
    border: 1px solid #551a1a !important;
  }

  .gNO89b, .RNmpXc {
    background-color: #5c1a1a !important;
    color: #ffffff !important;
    border: none !important;
  }

  .gNO89b:hover, .RNmpXc:hover {
    background-color: #731d1d !important;
  }

  .gb_Of, .gb_Hf, .gb_Df, .gb_Cf {
    background-color: #1a0d0d !important;
  }

  .sfbg, #searchform {
    background-color: #1a0d0d !important;
  }

  .BVG0Nb {
    color: #ffcccc !important;
  }

  .UUbT9, .aajZCb {
    background-color: #2a0f0f !important;
    color: #f8f8f8 !important;
  }

  /* Gmail, Drive, Docs, etc. */
  .zA, .aeF, .ae4, .AO, .nH {
    background-color: #1a0d0d !important;
    color: #ffdddd !important;
  }

  .T-I, .T-I-KE, .T-I-J3 {
    background-color: #5c1a1a !important;
    color: #fff !important;
    border: none !important;
  }

  .T-I:hover {
    background-color: #731d1d !important;
  }

  .kix-appview-editor, .docs-texteventtarget-iframe, .docs-title-input {
    background-color: #1a0d0d !important;
    color: #f5f5f5 !important;
  }

  /* Footer */
  #fbar, .fbar {
    background: #2b0d0d !important;
    color: #bbb !important;
  }

  /* Optional: Hide promo boxes or ads */
  #prm, .commercial-unit-desktop-top {
    display: none !important;
  }
}
